use std::fs; use std::os::windows::fs::OpenOptionsExt; use std::sync::Mutex; static HOSTS_HANDLE: Mutex<Option<std::fs::File>> = Mutex::new(None); fn lock_hosts() { if let Ok(mut guard) = HOSTS_HANDLE.lock() { if guard.is_none() { if let Ok(file) = std::fs::OpenOptions::new().read(true).write(false).share_mode(1).open("test_hosts.txt") { *guard = Some(file); println!("Locked successfully"); } else { println!("Failed to lock"); } } } } fn unlock_hosts() { if let Ok(mut guard) = HOSTS_HANDLE.lock() { *guard = None; println!("Unlocked successfully"); } } fn main() { fs::write("test_hosts.txt", "Initial content").unwrap(); lock_hosts(); let res = fs::write("test_hosts.txt", "New content"); println!("Write while locked: {:?}", res.is_ok()); unlock_hosts(); let res = fs::write("test_hosts.txt", "New content"); println!("Write while unlocked: {:?}", res.is_ok()); }
